// Validate perception request
const data = items[0].json;

if (!data.image_base64 && !data.image_url) {
  return [{ json: { error: 'Missing image (image_base64 or image_url required)', status: 'error' } }];
}

// Check frame timestamp
const ts = data.frame_timestamp_ms || Date.now();
return [{
  json: {
    image_base64: data.image_base64,
    image_url: data.image_url,
    frame_timestamp_ms: ts,
    session_id: data.session_id || 'unknown',
    device_id: data.device_id || 'unknown',
  }
}];

// Convert Vision API response to structured perception JSON
// NOTE: In production, replace this with a proper vision model
// (GPT-4V, Claude, or dedicated object detection model)

const visionData = items[0].json;
const labels = (visionData.labelAnnotations || []).map(l => ({
  name: l.description,
  score: l.score,
}));

// For a real implementation, this is where you'd call
// a multimodal LLM or dedicated object detection model
// to produce the full structured perception schema.

// DEMO FALLBACK: If no real vision model is wired, generate
// a conservative mock based on label presence.

const mockPerception = {
  scene_summary: "Scene analyzed. " + (labels.length > 0
    ? labels.slice(0, 5).map(l => l.name).join(', ') + ' detected.'
    : 'No prominent objects detected.'),
  objects: labels.filter(l => l.score > 0.6).slice(0, 10).map(l => ({
    type: categorize_label(l.name),
    position: 'center',
    estimated_distance_m: 5 + Math.random() * 10,
    distance_confidence: 0.5 + Math.random() * 0.3,
    blocks_path: false,
    risk: 'LOW',
  })),
  left_path: { clear: true, risk: 'LOW', confidence: 0.85 },
  center_path: { clear: true, risk: 'LOW', confidence: 0.88 },
  right_path: { clear: true, risk: 'LOW', confidence: 0.82 },
  overall_risk: 'LOW',
  confidence: 0.75,
  frame_timestamp_ms: items[0].json.frame_timestamp_ms,
  debug: {
    model_used: 'google_vision_labels (DEMO FALLBACK)',
    processing_time_ms: 200,
    raw_label_count: labels.length,
  },
};

function categorize_label(name) {
  const map = {
    'person': 'person', 'people': 'person', 'man': 'person', 'woman': 'person', 'child': 'person',
    'car': 'vehicle', 'cars': 'vehicle', 'truck': 'vehicle', 'bus': 'vehicle', 'van': 'vehicle',
    'motorcycle': 'motorcycle', 'bike': 'bicycle', 'bicycle': 'bicycle',
    'pole': 'pole', 'traffic light': 'sign', 'sign': 'sign', 'street sign': 'sign',
    'tree': 'tree', 'building': 'wall', 'wall': 'wall',
    'stairs': 'stairs', 'staircase': 'stairs',
    'bench': 'bench', 'trash': 'bin', 'bin': 'bin', 'garbage': 'bin',
    'door': 'door', 'fence': 'fence', 'road': 'road', 'sidewalk': 'sidewalk',
    'animal': 'animal', 'dog': 'animal', 'cat': 'animal',
  };
  return map[name.toLowerCase()] || 'unknown_obstacle';
}

return [{ json: mockPerception }];
